#include <WiFi.h>
#include <HTTPClient.h>

const char* ssid = "SEU_SSID";
const char* password = "SUA_SENHA";

const char* backendApiUrl = "http://192.168.1.100/api/traffic_time";

const int RED_LED_PIN = 16;
const int YELLOW_LED_PIN = 17;
const int GREEN_LED_PIN = 5;

enum TrafficLightState {
  RED_STATE,
  GREEN_STATE,
  YELLOW_STATE
};

TrafficLightState currentState = RED_STATE;
unsigned long stateStartTime = 0;
unsigned long currentGreenTime = 30000;
const unsigned long MIN_GREEN_TIME_MS = 10000;
const unsigned long YELLOW_DURATION_MS = 3000;
const unsigned long RED_DURATION_BEFORE_GREEN_MS = 5000;

void setTrafficLights(bool red, bool yellow, bool green) {
  digitalWrite(RED_LED_PIN, red ? HIGH : LOW);
  digitalWrite(YELLOW_LED_PIN, yellow ? HIGH : LOW);
  digitalWrite(GREEN_LED_PIN, green ? HIGH : LOW);
}

unsigned long requestNewGreenTime() {
  if (WiFi.status() != WL_CONNECTED) {
    return currentGreenTime;
  }

  HTTPClient http;
  http.begin(backendApiUrl);
  http.addHeader("Content-Type", "application/json");

  String httpRequestData = "{\"image_frame_id\": 123, \"traffic_density\": \"simulated_high\"}";

  int httpResponseCode = http.POST(httpRequestData);

  if (httpResponseCode == HTTP_CODE_OK) {
    String payload = http.getString();

    int startIndex = payload.indexOf("new_time_ms":") + 14;
    int endIndex = payload.indexOf("}", startIndex);
    if (startIndex != -1 && endIndex != -1) {
      String timeStr = payload.substring(startIndex, endIndex);
      unsigned long receivedTime = timeStr.toInt();
      if (receivedTime >= MIN_GREEN_TIME_MS) {
        return receivedTime;
      } else {
        return MIN_GREEN_TIME_MS;
      }
    }
  }
  http.end();
  return currentGreenTime;
}

void setup() {
  Serial.begin(115200);
  pinMode(RED_LED_PIN, OUTPUT);
  pinMode(YELLOW_LED_PIN, OUTPUT);
  pinMode(GREEN_LED_PIN, OUTPUT);

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi conectado.");
  Serial.print("Endereço IP: ");
  Serial.println(WiFi.localIP());

  setTrafficLights(true, false, false);
  stateStartTime = millis();
  currentState = RED_STATE;
}

void loop() {
  unsigned long currentTime = millis();

  switch (currentState) {
    case RED_STATE:
      if (currentTime - stateStartTime >= RED_DURATION_BEFORE_GREEN_MS) {
        currentGreenTime = requestNewGreenTime();
        setTrafficLights(false, false, true);
        stateStartTime = currentTime;
        currentState = GREEN_STATE;
      }
      break;

    case GREEN_STATE:
      if (currentTime - stateStartTime >= currentGreenTime) {
        setTrafficLights(false, true, false);
        stateStartTime = currentTime;
        currentState = YELLOW_STATE;
      }
      break;

    case YELLOW_STATE:
      if (currentTime - stateStartTime >= YELLOW_DURATION_MS) {
        setTrafficLights(true, false, false);
        stateStartTime = currentTime;
        currentState = RED_STATE;
      }
      break;
  }
}
